### 3. ViewModel and Data Persistence

1. **Persist Data with ViewModel**: Modify the `UserViewModel` to handle data persistence, such as saving user preferences.

```kotlin
// UserViewModel.kt
class UserViewModel : ViewModel() {
    private val _userData = MutableLiveData<UserData>()
    val userData: LiveData<UserData> = _userData

    fun fetchUserData() {
        viewModelScope.launch {
            val userData = repository.fetchUserData()
            _userData.value = userData
            // Persist data
            /* val preferences = getPreferences(Context.MODE_PRIVATE)
             val editor = preferences.edit()
             editor.putString("username", userData.name)
             editor.apply() */
        }
    }
}
```

2. **Retrieve Data from Preferences**: In the `MainActivity`, retrieve the user data from preferences and set it as the initial value for `userData`.

```kotlin
// MainActivity.kt
class MainActivity : AppCompatActivity() {

    private lateinit var viewModel: UserViewModel

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        setContentView(R.layout.activity_main)

        viewModel = ViewModelProvider(this).get(UserViewModel::class.java)

        // Observe the LiveData and update the UI
        viewModel.userData.observe(this, Observer { userData ->
            // Update UI with the fetched data
            userNameTextView.text = userData.name
        })

        // Fetch user data when the activity starts
        viewModel.fetchUserData()

        // Find the TextView in the layout
        val userNameTextView: TextView = findViewById(R.id.userNameTextView)

        // Load data from preferences
        val preferences = getPreferences(Context.MODE_PRIVATE)
        val userName = preferences.getString("username", "")
        if (userName.isNotEmpty()) {
            viewModel.userData.value = UserData(userName)
        }
    }
}
```

### 4. Repository Pattern

1. **Implement the Repository**: In the `UserRepository` class, implement a method to fetch user data from a network API.

```kotlin
// UserRepository.kt
class UserRepository(private val apiService: ApiService) {
    suspend fun fetchUserData(): UserData {
        return apiService.fetchUserData()
    }
}
```

2. **Create an API Service**: Create an `ApiService` interface to define the network requests.

```kotlin
// ApiService.kt
interface ApiService {
    @GET("user")
    suspend fun fetchUserData(): UserData
}
```

3. **Implement the API Service**: Create an implementation of `ApiService` using a library like Retrofit.

```kotlin
// ApiService.kt
object ApiService {
    private const val BASE_URL = "https://api.example.com/"

    private val client = OkHttpClient.Builder().build()

    private val retrofit = Retrofit.Builder()
        .baseUrl(BASE_URL)
        .addConverterFactory(GsonConverterFactory.create())
        .client(client)
        .build()

    val apiService: ApiService = retrofit.create(ApiService::class.java)
}
```

